function localeFlagImage(item,className="locale-flag-icon"){
 const image=document.createElement("img");image.className=className;image.alt="";image.setAttribute("aria-hidden","true");image.width=60;image.height=40;
 image.src="data:image/svg+xml;charset=utf-8,"+encodeURIComponent(localeFlagArt[item.code]||localeFlagArt.en);return image;
}
function syncLocaleFlag(host,item,className="locale-flag-icon"){
 if(!host)return;let image=host.querySelector(":scope > ."+className);if(!image){image=localeFlagImage(item,className);host.prepend(image)}else image.src=localeFlagImage(item,className).src;
}
