export function translateText(key){const lang=(()=>{try{return localStorage.getItem("cosmic-scrap-language")||"en"}catch{return"en"}})();return translations[lang]?.[key]||translations.en?.[key]||key}
function language(){try{const saved=localStorage.getItem("cosmic-scrap-language");return localeMeta.some(item=>item.code===saved)?saved:"en"}catch{return"en"}}
function renderLanguagePicker(prefix,lang){
 const wrap=document.getElementById(prefix+"-language-picker-control"),trigger=document.getElementById(prefix+"-language-current"),list=document.getElementById(prefix+"-language-options"),flag=document.getElementById(prefix+"-language-flag"),label=document.getElementById(prefix+"-language-label");
 if(!wrap||!trigger||!list)return;
 const selected=localeMeta.find(item=>item.code===lang)||localeMeta[0];
 if(flag)flag.src=flagAsset(selected.flagFile);
 if(label)label.textContent=selected.label;
 const close=()=>{list.hidden=true;trigger.setAttribute("aria-expanded","false");list.style.removeProperty("left");list.style.removeProperty("top");list.style.removeProperty("width");list.style.removeProperty("max-height")};
 const position=()=>{
  const rect=trigger.getBoundingClientRect(),gap=12,width=Math.min(300,Math.max(190,window.innerWidth-gap*2)),maxHeight=Math.min(360,Math.floor(window.innerHeight*.55));
  const left=Math.max(gap,Math.min(window.innerWidth-width-gap,rect.right-width));
  const below=window.innerHeight-rect.bottom-8,above=rect.top-8;
  const top=below>=Math.min(maxHeight,localeMeta.length*46+12)?rect.bottom+7:Math.max(gap,rect.top-Math.min(maxHeight,localeMeta.length*46+12)-7);
  list.style.position="fixed";list.style.left=left+"px";list.style.top=top+"px";list.style.width=width+"px";list.style.maxHeight=Math.max(150,Math.min(maxHeight,Math.max(below,above)))+"px";
 };
 if(!trigger.dataset.bound){
  trigger.dataset.bound="1";
  trigger.addEventListener("click",()=>{if(list.hidden){list.hidden=false;position();trigger.setAttribute("aria-expanded","true")}else close()});
  document.addEventListener("click",event=>{if(!wrap.contains(event.target)&&!list.contains(event.target))close()});
  document.addEventListener("keydown",event=>{if(event.key==="Escape"&&!list.hidden){close();trigger.focus()}});
  window.addEventListener("resize",()=>{if(!list.hidden)position()});
  window.addEventListener("scroll",()=>{if(!list.hidden)position()},true);
 }
 list.replaceChildren();
 for(const item of localeMeta){
  const option=document.createElement("button");option.type="button";option.className="language-picker-option";option.setAttribute("role","option");option.setAttribute("aria-selected",String(item.code===lang));
  const image=document.createElement("img");image.src=flagAsset(item.flagFile);image.alt="";image.setAttribute("aria-hidden","true");
  const name=document.createElement("span");name.textContent=item.label;
  const code=document.createElement("small");code.textContent=item.code;
  option.append(image,name,code);
  option.addEventListener("click",()=>{try{localStorage.setItem("cosmic-scrap-language",item.code)}catch{}applyLanguage(item.code);close();trigger.focus()});
  list.append(option);
 }
}
function replaceText(el,value){if(!el)return;const node=[...el.childNodes].find(n=>n.nodeType===Node.TEXT_NODE&&n.textContent.trim());if(node)node.textContent=value;else el.insertBefore(document.createTextNode(value),el.firstChild)}
function applyLanguage(lang=language()){
 const dict=translations[lang]||translations.en;document.documentElement.lang=lang;
 for(const el of document.querySelectorAll("button,label,strong,small,span,p,h1,h2,h3,kbd,option")){for(const node of el.childNodes){if(node.nodeType!==Node.TEXT_NODE||!node.textContent.trim())continue;if(node.__csEnglish===undefined)node.__csEnglish=node.textContent;const original=node.__csEnglish.trim();node.nodeValue=lang==="en"?node.__csEnglish:(dict[original]||node.__csEnglish)}}
 const selectedLocale=localeMeta.find(item=>item.code===lang)||localeMeta[0];const flagPath=flagAsset(selectedLocale.flagFile);const btn=document.getElementById("language-toggle");if(btn){btn.replaceChildren();const img=document.createElement("img");img.className="language-flag-image";img.src=flagPath;img.alt="";img.setAttribute("aria-hidden","true");btn.append(img,document.createTextNode(" "+selectedLocale.code));btn.setAttribute("aria-label","Language: "+selectedLocale.label)}const languageSelect=document.getElementById("setting-language");if(languageSelect)languageSelect.value=lang;const homeLanguageSelect=document.getElementById("home-language-select");if(homeLanguageSelect)homeLanguageSelect.value=lang;for(const id of ["setting-language-flag","home-language-flag"]){const image=document.getElementById(id);if(image)image.src=flagPath;}renderLanguagePicker("home",lang);renderLanguagePicker("setting",lang);
 const placeholders={"pilot@example.com":["pilot@example.com","pilot@ornek.com"],"At least 8 characters":["At least 8 characters","En az 8 karakter"],"Exact pilot username":["Exact pilot username","Tam oyuncu kullanıcı adı"],"8-character invite code":["8-character invite code","8 karakterli davet kodu"],"Write a respectful message…":["Write a respectful message…","Saygılı bir mesaj yaz…"]};document.querySelectorAll("input,textarea").forEach(el=>{const p=el.dataset.csEnPlaceholder||(el.dataset.csEnPlaceholder=el.placeholder);if(placeholders[p])el.placeholder=placeholders[p][lang==="tr"?1:0]});
 document.querySelectorAll("[data-i18n-en][data-i18n-tr]").forEach(el=>{const english=el.dataset.i18nEn;replaceText(el,dict[english]||(lang==="tr"?el.dataset.i18nTr:english))});
 document.querySelectorAll("[data-contract]").forEach(b=>{const keys={none:["ENDLESS SURVIVAL","No objective · play at your own pace"],salvager:["SALVAGE RUN","Collect 180 scrap · +2 Core"],elite:["ELITE HUNTER","Defeat an Elite · +3 Core"],storm:["STORMBREAKER","12 storm kills · +2 Core"]}[b.dataset.contract];if(!keys)return;const strong=b.querySelector("strong"),small=b.querySelector("small");if(strong)strong.textContent=dict[keys[0]]||keys[0];if(small)small.textContent=dict[keys[1]]||keys[1]});
 document.querySelectorAll("[data-skin]").forEach(b=>{const names={blue:"NEBULA",mint:"PHOTON",violet:"RIFT",amber:"SOLAR",red:"PHOENIX",gold:"SUPERNOVA"};const name=names[b.dataset.skin];const label=b.querySelector("span");if(label&&name)label.textContent=dict[name]||name});
 window.dispatchEvent(new Event("cosmic-scrap:language-changed"));
}
if(typeof document!=="undefined"){
 const cycleLanguage=()=>{const order=localeMeta.map(item=>item.code),next=order[(order.indexOf(language())+1)%order.length];try{localStorage.setItem("cosmic-scrap-language",next)}catch{}applyLanguage(next)};
 document.getElementById("language-toggle")?.addEventListener("click",cycleLanguage);
 document.getElementById("setting-language")?.addEventListener("change",event=>{const next=localeMeta.some(item=>item.code===event.target.value)?event.target.value:"en";try{localStorage.setItem("cosmic-scrap-language",next)}catch{}applyLanguage(next)});document.getElementById("home-language-select")?.addEventListener("change",event=>{const next=localeMeta.some(item=>item.code===event.target.value)?event.target.value:"en";try{localStorage.setItem("cosmic-scrap-language",next)}catch{}applyLanguage(next)});
 applyLanguage();
 if(!localStorage.getItem("cosmic-scrap-language-selected")){const modal=document.createElement("section");modal.id="language-welcome";modal.className="language-welcome";modal.setAttribute("role","dialog");modal.setAttribute("aria-modal","true");modal.innerHTML='<div class="language-welcome-card"><span class="language-welcome-kicker">TAVIRO · INDEPENDENT GAME</span><div class="language-welcome-emblem">✦</div><h2>WELCOME, PILOT.</h2><p>Choose your language to begin your journey. You can change it anytime in Settings.</p><div class="language-welcome-grid"></div><small>Your choice is saved on this device.</small></div>';const grid=modal.querySelector(".language-welcome-grid");localeMeta.forEach(item=>{const b=document.createElement("button");b.type="button";b.className="language-welcome-option";b.innerHTML='<span class="language-welcome-flag"></span><span class="language-welcome-name"></span><span class="language-welcome-code"></span>';const flagImage=document.createElement("img");flagImage.src=flagAsset(item.flagFile);flagImage.alt="";flagImage.setAttribute("aria-hidden","true");b.querySelector(".language-welcome-flag").append(flagImage);b.querySelector(".language-welcome-name").textContent=item.label;b.querySelector(".language-welcome-code").textContent=item.code;b.addEventListener("click",()=>{localStorage.setItem("cosmic-scrap-language",item.code);localStorage.setItem("cosmic-scrap-language-selected","1");applyLanguage(item.code);modal.remove()});grid.append(b)});document.body.append(modal);applyLanguage(language());grid.querySelector("button")?.focus();}
}


