export const REQUIRED_DYNAMIC_STATUS_KEYS=Object.freeze(Object.keys(accountStatusCopy.en));
if(typeof document!=="undefined"&&document.body){
 const localeObserver=new MutationObserver(records=>{
  const lang=language();
  for(const record of records)for(const added of record.addedNodes)applyStaticTextTo(added,lang);
 });
 localeObserver.observe(document.body,{childList:true,subtree:true});
 applyAllStaticText();
}

